use super::{assert_close, check_fixed, check_fixed_rescale, F32_TOL, F64_TOL, ROUND_TRIP_TOL};
use unitsnet_rs::*;

#[test]
fn volts_per_meter() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = x;
        assert_close(
            ElectricField::from_volts_per_meter(v).as_base(),
            base,
            F64_TOL,
        );
        let x: f64 = base;
        let back = x;
        assert_close(
            ElectricField::from_base(base).as_volts_per_meter(),
            back,
            F64_TOL,
        );
        assert_close(
            ElectricField::from_volts_per_meter(v).as_volts_per_meter(),
            v,
            ROUND_TRIP_TOL,
        );
        // f32 storage.
        assert_close(
            ElectricField::from_volts_per_meter(v as f32).as_base() as f64,
            base,
            F32_TOL,
        );
        assert_close(
            ElectricField::from_base(base as f32).as_volts_per_meter() as f64,
            back,
            F32_TOL,
        );
    }
}

#[test]
fn fixed_units() {
    check_fixed::<unit::electric_field::VoltPerMeter>();
    check_fixed_rescale::<unit::electric_field::VoltPerMeter>();
}

#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        ElectricField::new(v, ElectricFieldUnit::VoltPerMeter),
        ElectricField::from_volts_per_meter(v)
    );
    assert_eq!(
        ElectricField::from_base(v).convert_to(ElectricFieldUnit::VoltPerMeter),
        ElectricField::from_base(v).as_volts_per_meter()
    );
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = ElectricField::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            ElectricField::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in ElectricFieldUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        ElectricField::from_base(0.0).auto_unit().unit,
        ElectricFieldUnit::VoltPerMeter
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "V/m".parse::<ElectricFieldUnit>(),
        Ok(ElectricFieldUnit::VoltPerMeter)
    );
    assert_eq!(
        format!("2.5 {}", "V/m").parse::<ElectricField>(),
        Ok(ElectricField::new(2.5, ElectricFieldUnit::VoltPerMeter))
    );
    assert_eq!(
        "1 not-a-unit".parse::<ElectricField>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
